"""ViEW2026 の 3 つのビューアの文字列(8 言語)。

順は ``pocviewer.LANGS`` = ja, en, zh, tw, ko, de, hi, fr。数は **書かない** —— ``{名前}`` の穴に、
``tools/build_view2026_viewers.py`` が各 PoC を走らせた実測値を ``str.format`` で入れる(全言語で同じ穴)。
"""
from __future__ import annotations

import re

LANG_ORDER = ("ja", "en", "zh", "tw", "ko", "de", "hi", "fr")


def T(*xs: str) -> dict:
    """8 言語ぶんの辞書。数が合わなければその場で止める(1 言語だけ抜けたまま出さない)。"""
    if len(xs) != len(LANG_ORDER):
        raise ValueError("8 言語そろっていない: %d 本 %r" % (len(xs), xs[:1]))
    return dict(zip(LANG_ORDER, xs))


def fmt(d: dict, /, **kw) -> dict:
    """辞書の各言語に ``format`` で数を入れる。穴の集合が言語間で違えば止める。"""
    holes = {l: set(re.findall(r"\{(\w+)", v)) for l, v in d.items()}
    ref = holes["ja"]
    for l, h in holes.items():
        if h != ref:
            raise ValueError("穴が ja と違う言語がある: %s %s != %s" % (l, sorted(h), sorted(ref)))
    return {l: v.format(**kw) for l, v in d.items()}


